export function evaluate({ inputs, time }) {
  const g = 9.8;
  let u = Number(inputs && inputs.launchSpeed);
  if (!isFinite(u)) u = 3;
  u = sdk.clamp(u, 3, 5);
  const show = !(inputs && inputs.showArrows === "off");
  const tTop = u / g;
  const tEnd = 2 * u / g;
  let t = Number(time);
  if (!isFinite(t)) t = 0;
  t = sdk.clamp(t, 0, tEnd);

  let v = u - g * t;
  if (Math.abs(v) < 1e-9) v = 0;
  let h = u * t - g * t * t / 2;
  if (Math.abs(h) < 1e-12) h = 0;
  const a = -g;
  const apexHeight = u * u / (2 * g);

  const released = t >= tTop - 1e-9;
  const tr = released ? Math.max(0, t - tTop) : 0;
  let hv = released ? -g * tr : 0;
  if (Math.abs(hv) < 1e-9) hv = 0;
  const hh = -g * tr * tr / 2;
  const ha = released ? -g : 0;

  const launchY = 190, ppm = 95;
  const Y = (m) => launchY - m * ppm;
  const xT = 250, xH = 450;
  const vScale = 16, aScale = 7;

  const objs = [];
  objs.push(sdk.line("axis", 100, Y(1.4), 100, Y(-1.4), { role: "neutral" }));
  objs.push(sdk.text("axisLabel", 100, 22, "Height (m), up +", { align: "middle" }));
  objs.push(sdk.text("tickP1", 58, Y(1) + 5, "+1 m"));
  objs.push(sdk.text("tick0", 62, Y(0) + 5, "0 m"));
  objs.push(sdk.text("tickM1", 58, Y(-1) + 5, "-1 m"));
  objs.push(sdk.line("level", 110, launchY, 600, launchY, { role: "neutral", opacity: 0.25 }));
  objs.push(sdk.line("topLine", 205, Y(apexHeight), 345, Y(apexHeight), { role: "neutral", opacity: 0.45 }));
  objs.push(sdk.text("topText", 352, Y(apexHeight) + 5, "Top"));

  objs.push(...sdk.groundMark("launchMark", xT, launchY + 13, 30));
  objs.push(sdk.text("launchMarkLabel", 110, launchY + 24, "Launch mark"));
  objs.push(...sdk.gate("gate", xH, launchY + 13, { open: released, w: 40 }));
  objs.push(sdk.text("gateLabel", 500, launchY + 24, "Release gate"));

  objs.push(sdk.text("tossedLabel", xT, 22, "Tossed ball", { align: "middle" }));
  objs.push(sdk.text("heldLabel", xH, 22, "Held ball", { align: "middle" }));

  const yT = Y(h), yH = Y(hh);
  objs.push(sdk.circle("tossedBall", xT, yT, 24, { role: "output" }));
  objs.push(sdk.circle("heldBall", xH, yH, 24, { role: "observed" }));

  if (show) {
    objs.push(sdk.circle("tvDot", xT - 28, yT, 6, { role: "output" }));
    objs.push(...sdk.vector("tossedV", { x: xT - 28, y: yT }, { value: Math.abs(v), direction: v >= 0 ? "up" : "down" }, { scale: vScale, label: "v", role: "output" }));
    objs.push(...sdk.vector("tossedA", { x: xT + 28, y: yT }, { value: Math.abs(a), direction: "down" }, { scale: aScale, label: "a", role: "warning" }));
    objs.push(sdk.circle("hvDot", xH - 28, yH, 6, { role: "observed" }));
    objs.push(...sdk.vector("heldV", { x: xH - 28, y: yH }, { value: Math.abs(hv), direction: hv >= 0 ? "up" : "down" }, { scale: vScale, label: "v", role: "observed" }));
    objs.push(...sdk.vector("heldA", { x: xH + 28, y: yH }, { value: Math.abs(ha), direction: "down" }, { scale: aScale, label: "a", role: "warning" }));
  }

  const readouts = [
    { id: "tossedHeight", value: h },
    { id: "tossedVelocity", value: v },
    { id: "tossedAcceleration", value: a }
  ];
  const frame = sdk.frame(objs, { width: 640, height: 440, readouts });
  return {
    frame,
    quantities: {
      launchSpeed: u,
      gravity: g,
      velocity: v,
      acceleration: a,
      apexTime: tTop,
      height: h,
      tossedHeight: h,
      tossedVelocity: v,
      tossedAcceleration: a,
      heldHeight: hh,
      heldVelocity: hv,
      heldAcceleration: ha
    }
  };
}
